                    env.set_string(name.clone(), s);
                    ("assign_string", vec![], DenseArray::from_scalar(0.0))
                }
                Value::Array(val) => {
                    env.set(name.clone(), val.clone());
                    if is_param_ctor {
                        env.mark_param(name);
                    }
                    ("assign", vec![TraceValue::from_array(&val)], val)
                }
                Value::DeviceTensor { .. } => {
                    env.set_device_tensor(name.clone(), v.clone());
