//! Saga 23 step 002: auto-tagging from producer ops.
//!
//! Each test runs a small MLPL program that exercises one producer
//! rule and asserts the resulting binding carries the expected
//! `ValueTag` in `Environment::tags`.

use mlpl_core::{LossKind, ValueTag};
use mlpl_eval::{Environment, eval_program};
use mlpl_parser::{lex, parse};

fn run(src: &str, env: &mut Environment) {
    eval_program(&parse(&lex(src).unwrap()).unwrap(), env).unwrap();
}

#[test]
fn softmax_tags_result_as_probability() {
    let mut env = Environment::new();
    run("logits = randn(0, [2, 3])\nprobs = softmax(logits)\n", &mut env);
    assert_eq!(env.get_tag("probs"), Some(&ValueTag::Probability));
}

#[test]
fn sigmoid_tags_result_as_probability() {
    let mut env = Environment::new();
    run("x = randn(0, [4])\np = sigmoid(x)\n", &mut env);
    assert_eq!(env.get_tag("p"), Some(&ValueTag::Probability));
}

#[test]
fn log_softmax_tags_result_as_log_probability() {
    let mut env = Environment::new();
    run(
        "logits = randn(0, [2, 3])\nlp = log_softmax(logits)\n",
        &mut env,
    );
    assert_eq!(env.get_tag("lp"), Some(&ValueTag::LogProbability));
}

#[test]
fn cross_entropy_tags_result_as_loss_xent() {
    let mut env = Environment::new();
    run(
        "logits = randn(0, [2, 3])\ny = [0.0, 1.0]\nloss = cross_entropy(logits, y)\n",
        &mut env,
    );
    assert_eq!(
        env.get_tag("loss"),
        Some(&ValueTag::Loss {
            kind: LossKind::CrossEntropy
        })
    );
}

#[test]
fn mse_tags_result_as_loss_mse() {
    let mut env = Environment::new();
    run(
        "x = randn(0, [2, 2])\ny = randn(1, [2, 2])\nloss = mse(x, y)\n",
        &mut env,
    );
    assert_eq!(
        env.get_tag("loss"),
        Some(&ValueTag::Loss {
            kind: LossKind::Mse
        })
    );
}

#[test]
fn cosine_schedule_tags_result_as_learning_rate() {
    let mut env = Environment::new();
    run("lr = cosine_schedule(0, 100, 0.001, 0.01)\n", &mut env);
    assert_eq!(env.get_tag("lr"), Some(&ValueTag::LearningRate));
}

#[test]
fn linear_warmup_tags_result_as_learning_rate() {
    let mut env = Environment::new();
    run("lr = linear_warmup(5, 10, 0.01)\n", &mut env);
    assert_eq!(env.get_tag("lr"), Some(&ValueTag::LearningRate));
}

#[test]
fn grad_tags_result_as_gradient_with_wrt_name() {
    // grad expects the second arg to be a tracked param identifier.
    let mut env = Environment::new();
    let src = "W = param[2, 3]\nX = randn(0, [4, 2])\nY = matmul(X, W)\nloss = mean(Y)\ng = grad(loss, W)\n";
    run(src, &mut env);
    assert_eq!(
        env.get_tag("g"),
        Some(&ValueTag::Gradient {
            wrt: "W".to_string(),
        })
    );
}

#[test]
fn untagged_producer_yields_no_tag() {
    // matmul is not a Tier A producer; the result should remain untagged.
    let mut env = Environment::new();
    run("a = randn(0, [2, 3])\nb = randn(1, [3, 2])\nc = matmul(a, b)\n", &mut env);
    assert!(env.get_tag("c").is_none());
}

#[test]
fn untagged_inputs_do_not_block_producer_tag() {
    // The producer rule fires regardless of whether the inputs are
    // tagged. softmax over an untagged array still produces a
    // Probability binding.
    let mut env = Environment::new();
    run("x = randn(0, [3])\np = softmax(x)\n", &mut env);
    assert_eq!(env.get_tag("p"), Some(&ValueTag::Probability));
    assert!(env.get_tag("x").is_none());
}

#[test]
fn rebinding_overwrites_previous_tag() {
    // Re-assign a name with a different producer; the new tag wins.
    let mut env = Environment::new();
    let src = "x = randn(0, [2, 3])\nv = softmax(x)\nv = log_softmax(x)\n";
    run(src, &mut env);
    assert_eq!(env.get_tag("v"), Some(&ValueTag::LogProbability));
}

#[test]
fn rebinding_to_untagged_producer_clears_old_tag_only_via_clear() {
    // Re-binding to a non-producer expression keeps the old tag,
    // because side-table tags follow the binding NAME, not the
    // value. The next typing saga (step 005) adds the user-facing
    // :untag to clear deliberately. Documented behavior.
    let mut env = Environment::new();
    let src = "x = randn(0, [2, 3])\nv = softmax(x)\nv = matmul(x, x)\n";
    run(src, &mut env);
    // After the matmul re-binding, no NEW tag is set, so the old
    // Probability tag from softmax remains.
    assert_eq!(env.get_tag("v"), Some(&ValueTag::Probability));
}

