1	//! Saga 23 step 002: auto-tagging from producer ops.
2	//!
3	//! When an `Expr::Assign { name, value }` evaluates, we inspect the
4	//! right-hand side AST and -- for the curated Tier A producers --
5	//! attach a `ValueTag` to the binding via `Environment::set_tag`.
6	//!
7	//! Step 002 ships the *FnCall-driven* producer rules whose
8	//! builtins exist at the language surface today: softmax, sigmoid,
9	//! cross_entropy, cosine_schedule, linear_warmup, attention_weights,
10	//! and grad.
11	//!
12	//! Forward-looking tags whose producer builtins ship in later
13	//! sagas (LogProbability via `log_softmax`, KLDivergence via
14	//! `kl_divergence` from Saga 24, etc.) are not wired here -- they
15	//! land alongside their builtins. The `ValueTag` enum keeps the
16	//! variants reserved.
17	//!
18	//! Three rule clusters that need structural inspection of model
19	//! values -- Weight/Bias on `linear` / `embed` / `attention` param
20	//! creation, Logit on `apply` final-layer outputs, and Activation
21	//! on `apply` through activation layers -- are deferred to step
22	//! 003 because they require model_dispatch hooks and a structural
23	//! analysis pass over `ModelSpec` rather than a single AST match.
24	//!
25	//! Untyped producers stay untyped: a value with no rule simply
26	//! gets no tag and continues to flow through the language as a
27	//! plain DenseArray.
28	
29	use mlpl_core::{ActivationKind, LossKind, ValueTag};
30	use mlpl_parser::Expr;
31	
32	use crate::env::Environment;
33	use crate::model::{ActKind, ModelSpec};
34	
35	/// Inspect the right-hand side of an assignment and return the
36	/// `ValueTag` that producer should auto-attach to the binding,
37	/// or `None` if no rule matches.
38	pub(crate) fn for_assign(value: &Expr, env: &Environment) -> Option<ValueTag> {
39	    match value {
40	        Expr::FnCall { name, args, .. } if name == "apply" => apply_tag(args, env),
41	        Expr::FnCall { name, args, .. } => from_fncall(name, args),
42	        _ => None,
43	    }
44	}
45	
46	fn from_fncall(name: &str, args: &[Expr]) -> Option<ValueTag> {
47	    match name {
48	        "softmax" | "sigmoid" => Some(ValueTag::Probability),
49	        "cross_entropy" => Some(ValueTag::Loss {
50	            kind: LossKind::CrossEntropy,
51	        }),
52	        "cosine_schedule" | "linear_warmup" => Some(ValueTag::LearningRate),
53	        "attention_weights" => Some(ValueTag::AttentionMap),
54	        "grad" => gradient_tag(args),
55	        _ => None,
56	    }
57	}
58	
59	fn gradient_tag(args: &[Expr]) -> Option<ValueTag> {
60	    match args.get(1)? {
61	        Expr::Ident(name, _) => Some(ValueTag::Gradient { wrt: name.clone() }),
62	        _ => None,
63	    }
64	}
65	
66	/// Auto-tag for `apply(model_ident, X)`. Looks up the model in
67	/// the environment, walks its `ModelSpec` tail (chain -> last
68	/// child, residual -> inner), and returns:
69	/// - `Logit` if the tail is `Linear` or `LinearLora`,
70	/// - `Probability` if the tail is `Activation(Softmax)`,
71	/// - `Activation { layer: <model-binding-name>, kind }` for
72	///   `Activation(Tanh|Relu)`,
73	/// - `None` otherwise (rms_norm tail, attention tail, embedding
74	///   tail, non-Ident first arg, unknown model).
75	fn apply_tag(args: &[Expr], env: &Environment) -> Option<ValueTag> {
76	    let model_name = match args.first()? {
77	        Expr::Ident(n, _) => n,
78	        _ => return None,
79	    };
80	    let spec = env.get_model(model_name)?;
81	    tail_tag(spec, model_name)
82	}
83	
84	fn tail_tag(spec: &ModelSpec, layer: &str) -> Option<ValueTag> {
85	    match spec {
86	        ModelSpec::Chain(children) => children.last().and_then(|c| tail_tag(c, layer)),
87	        ModelSpec::Residual(inner) => tail_tag(inner, layer),
88	        ModelSpec::Linear { .. } | ModelSpec::LinearLora { .. } => Some(ValueTag::Logit),
89	        ModelSpec::Activation(kind) => activation_tail_tag(*kind, layer),
90	        ModelSpec::Embedding { .. } | ModelSpec::Attention { .. } | ModelSpec::RmsNorm { .. } => {
91	            None
92	        }
93	    }
94	}
95	
96	fn activation_tail_tag(kind: ActKind, layer: &str) -> Option<ValueTag> {
97	    match kind {
98	        ActKind::Softmax => Some(ValueTag::Probability),
99	        ActKind::Tanh => Some(ValueTag::Activation {
100	            layer: layer.into(),
101	            kind: ActivationKind::Tanh,
102	        }),
103	        ActKind::Relu => Some(ValueTag::Activation {
104	            layer: layer.into(),
105	            kind: ActivationKind::Relu,
106	        }),
107	    }
108	}

